const tenant = $('Buscar calendar ID do tenant').item.json[0];
const service = $('Buscar serviço').item.json[0];
const input = $('Chamado pelo Agente Cliente').item.json;

// Calcular janela de busca: próximos 7 dias úteis
const now = new Date();
const start = new Date(now);
start.setHours(0, 0, 0, 0);
const end = new Date(start);
end.setDate(end.getDate() + 10); // 10 dias para garantir 7 úteis

return [{
  json: {
    ...input,
    tenant_data: tenant,
    service_data: service,
    calendar_id: tenant.google_calendar_id,
    opening_hours: tenant.opening_hours,
    duration_minutes: service.duration_minutes,
    search_from: start.toISOString(),
    search_to: end.toISOString()
  }
}];

const busyEvents = $input.all().map(e => e.json) || [];
const ctx = $('Preparar busca de slots').item.json;
const openingHours = ctx.opening_hours || {};
const durationMin = ctx.duration_minutes || 30;

// Mapear dias da semana
const dayKeys = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];

// Gerar slots disponíveis
const availableSlots = [];
const now = new Date();

for (let dayOffset = 0; dayOffset < 10 && availableSlots.length < 5; dayOffset++) {
  const date = new Date(now);
  date.setDate(date.getDate() + dayOffset);
  if (date <= now) continue; // pular hoje se for tarde

  const dayKey = dayKeys[date.getDay()];
  const hours = openingHours[dayKey];
  if (!hours || !hours.open) continue; // dia fechado

  // Gerar slots de acordo com duração do serviço
  const [openH, openM] = hours.start.split(':').map(Number);
  const [closeH, closeM] = hours.end.split(':').map(Number);

  let slotStart = new Date(date);
  slotStart.setHours(openH, openM, 0, 0);
  const dayEnd = new Date(date);
  dayEnd.setHours(closeH, closeM, 0, 0);

  while (slotStart < dayEnd && availableSlots.length < 5) {
    const slotEnd = new Date(slotStart.getTime() + durationMin * 60000);

    if (slotEnd > dayEnd) break;

    // Verificar conflito com eventos existentes
    const hasConflict = busyEvents.some(event => {
      const evStart = new Date(event.start?.dateTime || event.start?.date);
      const evEnd = new Date(event.end?.dateTime || event.end?.date);
      return slotStart < evEnd && slotEnd > evStart;
    });

    if (!hasConflict) {
      availableSlots.push({
        starts_at: slotStart.toISOString(),
        ends_at: slotEnd.toISOString(),
        label: slotStart.toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: '2-digit' }) +
               ' às ' + slotStart.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })
      });
    }

    // Avançar 15 minutos
    slotStart = new Date(slotStart.getTime() + 15 * 60000);
  }
}

return [{
  json: {
    ...ctx,
    available_slots: availableSlots,
    slots_text: availableSlots.slice(0, 3).map((s, i) => `${i+1}. ${s.label}`).join('\n')
  }
}];
